<div class="customer-modal-backdrop" role="presentation"><section class="customer-modal" role="dialog" aria-modal="true" aria-labelledby="customer-modal-title"><div class="customer-modal-header"><div><span class="modal-eyebrow">Customer profile</span><h2 id="customer-modal-title"><?= e($customer['name']) ?></h2><span class="modal-code"><?= e($customer['customer_code']) ?></span></div><a class="customer-modal-close" aria-label="Close customer details" href="index.php?page=admin&amp;section=customers">×</a></div><div class="customer-modal-body"><div class="modal-status-row"><span class="status-badge status-<?= e($customer['status']) ?>"><?= e(ucfirst($customer['status'])) ?></span><span class="type-badge type-<?= e($customer['customer_type']) ?>"><?= e(ucwords(str_replace('_',' ',$customer['customer_type']))) ?></span></div><div class="modal-detail-grid"><div><span>Mobile Number</span><strong><?= e($customer['contact_number']) ?></strong></div><div><span>Secondary Number</span><strong><?= e($customer['secondary_contact_number'] ?: '-') ?></strong></div><div><span>Email Address</span><strong><?= e($customer['email'] ?: '-') ?></strong></div><div><span>NIC / Registration</span><strong><?= e($customer['nic_or_registration'] ?: '-') ?></strong></div><div class="modal-detail-wide"><span>Address</span><strong><?= nl2br(e($customer['address'] ?: '-')) ?></strong></div><div class="modal-detail-wide"><span>Notes</span><strong><?= nl2br(e($customer['notes'] ?: '-')) ?></strong></div></div><div class="modal-vehicles"><div class="modal-section-heading"><h3>Vehicles</h3><span><?= count($vehicles) ?> registered</span></div><?php if (!$vehicles): ?><p class="modal-empty">No vehicle records available.</p><?php else: ?><div class="modal-vehicle-list"><?php foreach ($vehicles as $vehicle): ?><article class="modal-vehicle-card"><div><strong><?= e($vehicle['vehicle_number']) ?></strong><span><?= e($vehicle['make'] ? $vehicle['make'] . ' ' : '') ?><?= e($vehicle['model']) ?></span></div><div><span>Type</span><strong><?= e($vehicle['vehicle_type']) ?></strong></div><div><span>Mileage</span><strong><?= e($vehicle['current_mileage'] !== null ? $vehicle['current_mileage'] . ' km' : '-') ?></strong></div></article><?php endforeach; ?></div><?php endif; ?></div></div><div class="customer-modal-footer"><a class="btn btn-light" href="index.php?page=admin&amp;section=customers">Close</a><a class="btn btn-primary" href="index.php?page=admin&amp;section=customers-edit&amp;id=<?= (int) $id ?>">Edit Customer</a></div></section></div>
